import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import { get_all_org_suppliers } from "@/mixins/GetSuppliers.js";
import { create_list_edit_delete_material } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_material_unit } from "@/mixins/GetMaterialUnit.js";
export default {
  props: {
    materialedition: Boolean,
    rowInfo: Object
  },
  mixins: [get_all_org_suppliers, get_material_unit],
  data() {
    return {
      materialName: "",
      materialunit: [],
      supplierName: [],
      unititems: [],
      unitName: "",
      loading: false,
      searchF: "",
      userArray: []
    };
  },
  watch: {
    materialedition: {
      async handler() {
        if (this.materialedition == true) {
          await Promise.all([this.get_material_unit(), this.get_all_org_suppliers()]);
          await this.fetch_details();
          // localStorage.setItem(
          //   "material_unit",
          //   JSON.stringify(this.rowInfo.material_unit)
          // );
          this.unitName = this.rowInfo.material_unit_id;
          this.materialName = this.rowInfo.material_name;
          // this.materialunit = JSON.parse(localStorage.getItem("material_unit"));
          this.supplierName = this.rowInfo.supplier_name == undefined ? "" : this.rowInfo.supplier_name;
        }
      },
      immediate: true
    }
  },
  computed: {},
  methods: {
    removecc(item) {
      this.materialunit.splice(this.materialunit.indexOf(item), 1);
    },
    fetch_details() {
      this.unitmaterials.forEach(element => {
        this.unititems.push({
          text: element.material_unit_name,
          value: element.material_unit_id
        });
      });
      this.orgSupplier.forEach(element => {
        this.userArray.push({
          full_user_name: element.supplier_name,
          user_id: element.suppliers_id
        });
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_material, {
          input: {
            organization_id: data.organization.organization_id,
            material_id: this.rowInfo.material_id,
            action_type: "UPDATE_MATERIAL",
            material_name: this.materialName,
            material_unit_id: this.unitName,
            supplier_name: this.supplierName == null ? "" : this.supplierName
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_delete_material);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
